package au.aumanet.app;
import java.io.*;import org.json.*;
/** Exact production transaction worker; flash/Android/network boundaries declared by actor.mjs. */
public final class NodeUpdateActorTest{
 static int tests,assertions;static void check(boolean b){assertions++;if(!b)throw new AssertionError("Native update transaction regression");}
 static void completed(File work,int mode)throws Exception{tests++;NodeUpdateActorHarness h=new NodeUpdateActorHarness(work,mode);h.run();check(h.operation.phase.equals("complete"));check(h.starts==1&&h.activations==1&&h.confirmations==1);check(h.journal.current()==null&&h.current.get()==null&&h.closed==1);}
 static void stopped(File work)throws Exception{tests++;NodeUpdateActorHarness h=new NodeUpdateActorHarness(work,3);h.run();check(h.operation.phase.equals("unknown"));check(h.activations==1&&h.confirmations==0&&h.postQueries==0);check(h.journal.current().getBoolean("activated")&&h.current.get()==null&&h.closed==1);NodeUpdateActorHarness before=new NodeUpdateActorHarness(work,4);before.run();check(before.operation.phase.equals("cancelled"));check(before.starts==0&&before.activations==0&&before.confirmations==0&&before.journal.current()==null);}
 static void rebootAndMismatch(File work)throws Exception{completed(work,7);tests++;NodeUpdateActorHarness wrong=new NodeUpdateActorHarness(work,8);wrong.run();check(wrong.operation.phase.equals("unknown"));check(wrong.activations==1&&wrong.confirmations==0);NodeUpdateActorHarness rollback=new NodeUpdateActorHarness(work,9);rollback.run();check(rollback.operation.phase.equals("rolled-back"));check(rollback.activations==1&&rollback.confirmations==0&&rollback.journal.current()==null);}
 static void failed(File work)throws Exception{tests++;NodeUpdateActorHarness late=new NodeUpdateActorHarness(work,5);late.run();check(late.operation.phase.equals("unknown"));check(late.activations==1&&late.confirmations==0&&late.journal.current().getBoolean("activated"));NodeUpdateActorHarness upload=new NodeUpdateActorHarness(work,6);upload.run();check(upload.operation.phase.equals("failed"));check(upload.starts==1&&upload.activations==0&&upload.journal.current()==null);}
 static void preparation(File work)throws Exception{tests++;for(int mode:new int[]{10,11,12}){NodeUpdateActorHarness h=new NodeUpdateActorHarness(work,mode);h.run();check(h.operation.phase.equals("failed"));check(h.starts==0&&h.queries==0&&h.activations==0&&h.confirmations==0);String expected=mode==10?"QUIET_REFUSED":mode==11?"RETAINED_NOT_CURRENT":"QUIET_RETAINED_NOT_CURRENT";check(android.util.Log.last.equals("AuMaNETNodeUpdate "+expected+" OWNED_OPERATION_FAILED"));check(h.journal.current()==null&&h.current.get()==null);}}
 public static void main(String[]args)throws Exception{File work=new File(args[0]);NodeUpdateHostTest.setup(work);completed(work,0);completed(work,1);completed(work,2);stopped(work);failed(work);rebootAndMismatch(work);preparation(work);System.out.println(new JSONObject().put("status","pass").put("testCount",tests).put("assertionCount",assertions));}
}
